"""Original Force practice drafts; local, deterministic, no DB/network/approval.
40 concept MCQ +16 numeric families x10; 40 concept SQ +6 x5;
24 CQ families x5. Numeric variants are disclosed, not independent board questions.
Run --check for reproducibility. Never mutates previous chapters.
"""
from pathlib import Path
from fractions import Fraction as F
from decimal import Decimal, ROUND_HALF_UP
from collections import Counter
import hashlib, html, json, sys

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'content/question-bank/ssc/physics/chapter-3'
DOC=ROOT/'docs/question-bank/ssc-physics'
TOPIC='৩য় অধ্যায়: বল'
PAGE='নিজস্ব অনুশীলনী; বোর্ড-প্রশ্ন নয়; মূল বইয়ের পৃষ্ঠা যাচাই বাকি'
items=[]
audit=[]

def fmt(x):
    x=F(x)
    d=(Decimal(x.numerator)/Decimal(x.denominator)).quantize(Decimal('.000001'),rounding=ROUND_HALF_UP)
    return format(d,'f').rstrip('0').rstrip('.') or '0'

def add(kind,text,explanation,family,calc=None,**kw):
    items.append(dict(type=kind,text=text,explanation=explanation,page=PAGE,difficulty=kw.pop('difficulty','MEDIUM'),**kw))
    m=dict(index=len(items),kind=kind,family=family,originalPractice=True,teacherApproved=False)
    if calc:m['calculation']=calc
    audit.append(m)

def mcq(q,answer,wrong,why,family,calc=None):
    options=[str(answer),*map(str,wrong)];assert len(set(options))==len(options)==4,(q,options)
    pos=sum(x['type']=='MCQ' for x in items)%4;options.insert(pos,options.pop(0))
    add('MCQ',q,why,family,calc,options=dict(zip('ABCD',options)),correct='ABCD'[pos])

