def calc(f,n):
    m=2+n;a=F(n+2,2)
    if f=='force':
        ans=m*a
        return f'{m} kg ভরের বস্তুর ত্বরণ +{fmt(a)} m/s²। লব্ধ বল কত?',ans,' N',f'F = ma = {m}×{fmt(a)} = {fmt(ans)} N।',dict(m=m,a=a)
    if f=='acceleration':
        force=18+n*6;ans=F(force,m)
        return f'{m} kg ভরের বস্তুর ওপর +{force} N লব্ধ বল ক্রিয়া করে। ত্বরণ কত?',ans,' m/s²',f'a = F/m = {force}/{m} = {fmt(ans)} m/s²।',dict(m=m,force=force)
    if f=='mass':
        a=2+n;force=(3+n)*a;ans=F(force,a)
        return f'এক বস্তুর ওপর {force} N লব্ধ বল দিলে {a} m/s² ত্বরণ হয়। ভর কত?',ans,' kg',f'm = F/a = {force}/{a} = {fmt(ans)} kg।',dict(force=force,a=a)
    if f=='opposed':
        right=20+n*4;left=5+n;ans=F(right-left,m)
        return f'{m} kg ব্লকে ডানে {right} N ও বামে {left} N বল ক্রিয়া করে। অন্য অনুভূমিক বল নেই। ডান ধনাত্মক হলে ত্বরণ কত?',ans,' m/s²',f'Fনিট = {right}−{left} = {right-left} N; a = ({right}−{left})/{m} = {fmt(ans)} m/s²।',dict(m=m,right=right,left=left)
    if f=='momentum':
        v=4+n;ans=m*v
        return f'{m} kg বস্তু পূর্বদিকে {v} m/s বেগে চলে। ভরবেগের মান কত?',ans,' kg·m/s',f'p = mv = {m}×{v} = {ans} kg·m/s, পূর্বে।',dict(m=m,v=v)
    if f=='impulse':
        force=15+n*5;t=F(n+2,10);ans=force*t
        return f'এক বস্তুর ওপর +{force} N ধ্রুব লব্ধ বল {fmt(t)} s ক্রিয়া করে। ঘাত কত?',ans,' N·s',f'J = FΔt = {force}×{fmt(t)} = {fmt(ans)} N·s।',dict(force=force,t=t)
    if f=='momentum-change':
        u=2+n;v=u+5+n;ans=m*(v-u)
        return f'{m} kg বস্তুর বেগ একই অক্ষে +{u} m/s থেকে +{v} m/s হয়। ভরবেগের পরিবর্তন কত?',ans,' kg·m/s',f'Δp = m(v−u) = {m}×({v}−{u}) = {ans} kg·m/s।',dict(m=m,u=u,v=v)
    if f=='average-force':
        u=3+n;v=12+n*2;t=F(n+2,2);ans=F(m*(v-u))/t
        return f'{m} kg বস্তুর বেগ {fmt(t)} s-এ +{u} m/s থেকে +{v} m/s হয়। গড় লব্ধ বল কত?',ans,' N',f'Fগড় = Δp/Δt = {m}×({v}−{u})/{fmt(t)} = {fmt(ans)} N।',dict(m=m,u=u,v=v,t=t)
    if f=='stopping-force':
        u=8+n*2;t=2+n;ans=F(m*u,t)
        return f'{m} kg বস্তু {u} m/s আদিদ্রুতি থেকে {t} s-এ থামে। একই সরল অক্ষে গড় লব্ধ বাধাদানকারী বলের মান কত?',ans,' N',f'ঘাতের মান = m u = {m*u} N·s; বলের মান = {m*u}/{t} = {fmt(ans)} N। দিক আদিবেগের বিপরীতে।',dict(m=m,u=u,t=t)
    if f=='friction':
        mu=F(n+1,20);g=10;ans=mu*m*g
        return f'{m} kg ব্লক সমতল মেঝেতে পিছলাচ্ছে। μₖ = {fmt(mu)}, g = 10 m/s²; অন্য উল্লম্ব বল নেই, উল্লম্ব ত্বরণ শূন্য। f = μₖN মডেলে ঘর্ষণের মান কত?',ans,' N',f'N = mg = {m*g} N; f = μₖN = {fmt(mu)}×{m*g} = {fmt(ans)} N।',dict(m=m,mu=mu,g=g)
    if f=='coefficient':
        N=40+n*10;mu=F(n+1,20);fr=mu*N;ans=mu
        return f'এক পিছলানো ব্লকে অভিলম্ব বল {N} N ও গতিঘর্ষণ {fmt(fr)} N। f = μₖN মডেলে ঘর্ষণ সহগ কত?',ans,'',f'μₖ = f/N = {fmt(fr)}/{N} = {fmt(ans)}; একক নেই।',dict(N=N,fr=fr)
    if f=='weight':
        g=F(98,10);ans=m*g
        return f'{m} kg ভরের বস্তুর ওজন কত? g = 9.8 m/s²।',ans,' N',f'W = mg = {m}×9.8 = {fmt(ans)} N।',dict(m=m,g=g)
    if f=='sticking':
        M=3+n;u=5+n;ans=F(m*u,m+M)
        return f'মসৃণ অনুভূমিক পথে {m} kg গাড়ি +{u} m/s বেগে এসে স্থির {M} kg গাড়িতে লেগে একসঙ্গে চলে। বাহ্যিক অনুভূমিক ঘাত শূন্য ধরলে যৌথ বেগ কত?',ans,' m/s',f'mu = (m+M)V; V = {m}×{u}/({m}+{M}) = {fmt(ans)} m/s।',dict(m=m,M=M,u=u)
    if f=='recoil':
        bullet=F(n+1,100);speed=100+n*20;gun=2+n;ans=bullet*speed/gun
        return f'স্থির বন্দুক থেকে {fmt(bullet)} kg গুলি সামনে {speed} m/s ভূমি-সাপেক্ষ বেগে বেরোয়। গুলি বের হওয়ার পর বন্দুকের ভর {gun} kg। বাহ্যিক অনুভূমিক ঘাত নেই। বন্দুকের পশ্চাদ্বেগের মান কত?',ans,' m/s',f'প্রথমে মোট ভরবেগ শূন্য; M V + m v = 0। পশ্চাদ্বেগের মান = {fmt(bullet)}×{speed}/{gun} = {fmt(ans)} m/s।',dict(bullet=bullet,speed=speed,gun=gun)
    if f=='braking-time':
        u=8+n*2;brake=20+n*10;ans=F(m*u,brake)
        return f'{m} kg ট্রলি {u} m/s বেগে চলছে। আদিবেগের বিপরীতে {brake} N ধ্রুব লব্ধ বল থামা পর্যন্ত ক্রিয়া করে। থামতে সময় কত?',ans,' s',f'F t = m u-এর মান থেকে t = {m}×{u}/{brake} = {fmt(ans)} s।',dict(m=m,u=u,brake=brake)
    if f=='final-velocity':
        u=3+n;force=10+n*2;t=2+n;ans=F(u)+F(force*t,m)
        return f'{m} kg বস্তুর আদিবেগ +{u} m/s। +{force} N ধ্রুব লব্ধ বল {t} s ক্রিয়া করলে শেষবেগ কত?',ans,' m/s',f'a = F/m; v = u+(F/m)t = {u}+({force}/{m})×{t} = {fmt(ans)} m/s।',dict(m=m,u=u,force=force,t=t)
    raise ValueError(f)

FAMILIES=['force','acceleration','mass','opposed','momentum','impulse','momentum-change','average-force','stopping-force','friction','coefficient','weight','sticking','recoil','braking-time','final-velocity']
for f in FAMILIES:
    for n in range(10):
        q,r,unit,why,p=calc(f,n);r=F(r);wrong=[]
        for x in [r*2,r/2,r*F(3,2),r+1,r-1,r*10]:
            text=fmt(x)+unit
            if x>=0 and text!=fmt(r)+unit and text not in wrong:wrong.append(text)
            if len(wrong)==3:break
        mcq(q,fmt(r)+unit,wrong,why,f,dict(params={k:str(v) for k,v in p.items()},expected=str(r),unit=unit))

SHORTS='''জড়তা কাকে বলে এবং ভরকে এর পরিমাপ বলা হয় কেন?|বস্তু তার স্থির বা সমবেগের অবস্থা বজায় রাখতে চায়—এ প্রবণতা জড়তা। একই লব্ধ বলে বেশি ভরের ত্বরণ কম হয়; তাই ভর জড়তার পরিমাপ।
লব্ধ বল শূন্য হলেও একাধিক বল কাজ করতে পারে কি? উদাহরণ দাও।|হ্যাঁ। টেবিলে স্থির বইয়ের ওপর নিচে ওজন ও ওপরে সমান অভিলম্ব বল কাজ করে। তাদের ভেক্টর যোগফল শূন্য।
সমবেগে চলতে সবসময় সামনের দিকে লব্ধ বল দরকার—এ কথা ভুল কেন?|নিউটনীয় জড় কাঠামোয় সমবেগে ত্বরণ শূন্য, তাই লব্ধ বল শূন্য। ঘর্ষণ থাকলে তাকে সামলাতে টান লাগে, কিন্তু টানই লব্ধ বল নয়।
বাস হঠাৎ শুরু করলে দাঁড়ানো যাত্রী পেছনে হেলেন কেন?|পায়ের সংস্পর্শ বাসের সঙ্গে নিচের অংশকে এগোয়। শরীরের ওপরের অংশ স্থির থাকার জড়তায় আগের অবস্থায় থাকতে চায় বলে আপেক্ষিকভাবে পেছনে হেলে পড়ে।
চলন্ত বাসে হঠাৎ ব্রেক করলে সিটবেল্টের ভূমিকা কী?|শরীর জড়তার জন্য সামনে চলতে চায়। সিটবেল্ট শরীরে বাধাদানকারী বল দিয়ে গাড়ির সঙ্গে থামাতে সাহায্য করে; একা জড়তা কোনো আলাদা সামনের বল নয়।
নিউটনের প্রথম সূত্রকে জড়তার সূত্র বলা হয় কেন?|এতে বাহ্যিক লব্ধ বল না থাকলে বস্তুর স্থির বা সরলরেখায় সমবেগের অবস্থা বজায় থাকার কথা বলা হয়। এই অবস্থা বদলাতে অনীহাই জড়তা।
বল ও ত্বরণের দিকের সম্পর্ক ধ্রুব ভরের ক্ষেত্রে লেখো।|Fনিট = ma। ভর ধনাত্মক স্কেলার বলে ত্বরণ লব্ধ বলের দিকেই হয়; বেগের দিক অবশ্যই সেই দিক হবে এমন নয়।
একটি বলের মান দিয়ে সবসময় ত্বরণ বের করা যায় না কেন?|আরও বল থাকলে তাদের ভেক্টর যোগফল নিতে হয়। ত্বরণ a = Fনিট/m; একা প্রয়োগ করা বল থেকে প্রতিরোধ বাদ না দিলে ভুল হবে।
নিউটনের দ্বিতীয় সূত্রে F বলতে প্রয়োগ করা বল না লব্ধ বল বোঝায়?|বস্তুর ওপরের সব বাহ্যিক বলের ভেক্টর যোগফল বা লব্ধ বল। ঘর্ষণ বা অন্য বল থাকলে সেটিও অন্তর্ভুক্ত করতে হয়।
1 নিউটন বলের সংজ্ঞা দাও।|যে লব্ধ বল 1 kg ভরের বস্তুকে 1 m/s² ত্বরণ দেয় তার মান 1 N। অর্থাৎ 1 N = 1 kg·m/s²।
দ্বিতীয় সূত্র দিয়ে প্রথম সূত্রের বক্তব্য কীভাবে পাওয়া যায়?|ধ্রুব ভরের জন্য Fনিট = ma। লব্ধ বল শূন্য হলে ত্বরণ শূন্য, ফলে বেগ অপরিবর্তিত থাকে—স্থির বস্তু স্থির বা চলমান বস্তু সরলরেখায় সমবেগে চলে।
ক্রিয়া ও প্রতিক্রিয়ার তিনটি বৈশিষ্ট্য লেখো।|তারা একই আন্তঃক্রিয়ায় একসঙ্গে সৃষ্টি হয়, মানে সমান ও বিপরীতমুখী। তারা দুই ভিন্ন বস্তুর ওপর কাজ করে; একই বস্তুর সাম্যকারী বল নয়।
টেবিলে বইয়ের ওজন ও অভিলম্ব বলকে ক্রিয়া-প্রতিক্রিয়া বলা যায় না কেন?|দুটিই বইয়ের ওপর কাজ করে, যদিও সাম্যাবস্থায় মান সমান। তৃতীয় সূত্রের যুগল ভিন্ন বস্তুর ওপর: পৃথিবী–বইয়ের মহাকর্ষীয় যুগল এবং টেবিল–বইয়ের সংস্পর্শ যুগল আলাদা।
হাঁটার সময় মাটির ঘর্ষণ সামনের দিকে হতে পারে কেন?|পা মাটিকে পেছনে ঠেলে এবং পায়ের আপেক্ষিক পিছলানোর প্রবণতা পেছনে। মাটি পায়ের ওপর সামনের দিকে স্থিতি ঘর্ষণ দিয়ে মানুষকে এগোতে সাহায্য করে।
নৌকা থেকে তীরে লাফালে নৌকা পেছায় কেন?|ব্যক্তি নৌকাকে পেছনে ঠেলে, নৌকা ব্যক্তিকে সামনে ঠেলে। অনুভূমিক বাহ্যিক ঘাত উপেক্ষায় ব্যক্তি ও নৌকার মোট ভরবেগ সংরক্ষিত হয়।
ভরবেগ ভেক্টর কেন? একক লেখো।|p = mv-তে ভর স্কেলার কিন্তু বেগ ভেক্টর। তাই ভরবেগের দিক বেগের দিকেই; SI একক kg·m/s।
একই ভরবেগে হালকা ও ভারী বস্তুর বেগের তুলনা করো।|মানের ক্ষেত্রে v = p/m। একই অশূন্য ভরবেগে ভর বেশি হলে বেগের মান কম; দিক ভরবেগের দিকেই।
সমান দ্রুতি নিয়ে বিপরীত দিকে চলা সমান ভরের দুই বস্তুর মোট ভরবেগ ও মোট দ্রুতি সম্পর্কে কী বলবে?|তাদের দিকযুক্ত ভরবেগ সমান বিপরীত বলে মোট ভরবেগ শূন্য। কিন্তু প্রতিটির দ্রুতি অশূন্য; ভরবেগ যোগ করার সময় দিক উপেক্ষা করা যাবে না।
বলের ঘাত ও ভরবেগের পরিবর্তনের সম্পর্ক ব্যাখ্যা করো।|ধ্রুব ভরে Fগড় = Δp/Δt। সময় দিয়ে গুণে Fগড়Δt = Δp; বামপাশ লব্ধ বলের ঘাত।
ঘাত ও কাজ এক নয় কেন?|ঘাত বল × সময়, একক N·s এবং ভরবেগ বদলায়। কাজ বল ও সরণের সম্পর্কিত গুণফল, একক N·m; দুটি ভিন্ন রাশি।
ক্রিকেট বল ধরার সময় হাত পেছানো কেন আঘাত কমাতে পারে?|একই আদিভরবেগ থেকে বল থামাতে একই ভরবেগ-পরিবর্তন দরকার। হাত পেছালে থামার সময় বাড়ে, তাই গড় বলের মান কমে।
উঁচু থেকে নরম বিছানায় পড়া শক্ত মেঝের চেয়ে কম আঘাত দিতে পারে কেন?|একই পতন-বেগ থেকে থামার সময় ও দূরত্ব নরম স্তরে সাধারণত বেশি হয়। একই ভরবেগ-পরিবর্তন দীর্ঘ সময়ে হওয়ায় গড় লব্ধ বাধাদানকারী বল কমে।
কোনো সিস্টেমের ভরবেগ সংরক্ষণের সঠিক শর্ত কী?|নির্বাচিত সিস্টেমের ওপর বিবেচিত সময়ে লব্ধ বাহ্যিক ঘাত শূন্য হতে হবে। অভ্যন্তরীণ বলগুলো পারস্পরিক যুগলে মোট ভরবেগ বদলায় না।
দুটি বস্তুর সংঘর্ষে একটি বস্তুর ভরবেগ সবসময় সংরক্ষিত হয় না কেন?|অন্য বস্তুটি তার ওপর বল ও ঘাত দেয়। দুই বস্তুকে একসঙ্গে সিস্টেম ধরলে এবং লব্ধ বাহ্যিক ঘাত শূন্য হলে কেবল মোট ভরবেগ সংরক্ষণ প্রযোজ্য।
সংঘর্ষে দুটি বস্তু লেগে গেলে যৌথ বেগ বের করার পদ্ধতি লেখো।|একই অক্ষ ধরে আগে মোট ভরবেগ m₁u₁+m₂u₂ নির্ণয় করি। বাহ্যিক ঘাত শূন্য হলে (m₁+m₂)V-এর সঙ্গে সমান করে V পাই; বেগের চিহ্ন রাখতে হয়।
বন্দুকের পশ্চাদ্বেগ সাধারণত গুলির বেগের চেয়ে কম কেন?|অনুভূমিক মোট ভরবেগ শূন্যে M V = −m v। বন্দুকের ভর গুলির ভরের চেয়ে অনেক বেশি বলে তার বেগের মান অনুপাতে কম হয়।
বিস্ফোরণে স্থির বস্তুর দুটি টুকরা বিপরীত দিকে যেতে পারে কেন?|বাহ্যিক ঘাত উপেক্ষায় প্রথমে মোট ভরবেগ শূন্য থাকে। টুকরার ভরবেগগুলো সমান বিপরীত হলে তাদের যোগ শূন্য বজায় থাকে; ভর আলাদা হলে বেগও আলাদা হয়।
ঘর্ষণের দিক নির্ধারণে বস্তুর সামগ্রিক গতির বদলে কী দেখবে?|সংস্পর্শতলে দুটি পৃষ্ঠের আপেক্ষিক পিছলানো বা তার প্রবণতা দেখব। ঘর্ষণ সেটির বিরোধিতা করে; মাটির তুলনায় গতির দিকের বিপরীত হওয়া বাধ্যতামূলক নয়।
স্থিতি ও গতিঘর্ষণের পার্থক্য লেখো।|আপেক্ষিক পিছলানো না হলে স্থিতি ঘর্ষণ প্রয়োজনমতো সীমা পর্যন্ত মান নেয়। পিছলানো চললে গতিঘর্ষণ কাজ করে; সরল মডেলে তার মান μₖN।
স্থিতি ঘর্ষণকে সবসময় μₛN ধরে নেওয়া ভুল কেন?|μₛN শুধু সর্বোচ্চ স্থিতি ঘর্ষণ। এর কম টানেও ব্লক স্থির থাকলে ঘর্ষণ প্রয়োজনীয় টানের সমান হয়, সর্বোচ্চ সীমার সমান নয়।
ঘর্ষণ সহগ কেন মাত্রাহীন?|সহগ হলো ঘর্ষণ বল ও অভিলম্ব বলের অনুপাত। লব ও হরে একই N একক ও একই বলের মাত্রা কাটাকাটি হয়।
অভিলম্ব বলকে সব অবস্থায় mg বলা যায় না কেন?|অন্য উল্লম্ব বল বা উল্লম্ব ত্বরণ থাকলে N বদলায়। শুধু সমতল পৃষ্ঠে অন্য উল্লম্ব বল নেই ও উল্লম্ব ত্বরণ শূন্য হলে N = mg।
ঘর্ষণের দুটি উপকার ও একটি অপকার লেখো।|হাঁটার গ্রিপ ও গাড়ির ব্রেকিংয়ে ঘর্ষণ প্রয়োজন। যন্ত্রে অনাবশ্যক ঘর্ষণ তাপ ও ক্ষয় সৃষ্টি করতে পারে।
ঘর্ষণ কমানোর দুটি পদ্ধতি লেখো।|উপযুক্ত তৈলাক্তকরণ এবং বল-বিয়ারিং বা চাকা ব্যবহার। তবে প্রয়োজনীয় গ্রিপের স্থানে ইচ্ছামতো ঘর্ষণ কমানো নিরাপদ নয়।
গাড়ির টায়ারে খাঁজ ও রাস্তায় গ্রিপ গুরুত্বপূর্ণ কেন?|খাঁজ পানি বের হতে ও কার্যকর সংস্পর্শ বজায় রাখতে সাহায্য করে। প্রয়োজনীয় ঘর্ষণ না থাকলে ত্বরণ, মোড় নেওয়া ও ব্রেকিংয়ে পিছলানোর ঝুঁকি বাড়ে।
ভর ও ওজনের পার্থক্য লেখো।|ভর জড়তার পরিমাপ, স্কেলার, SI একক kg। ওজন মহাকর্ষীয় বল W = mg, ভেক্টর, একক N; g বদলালে ওজন বদলায়।
প্রকৃতির চার মৌলিক আন্তঃক্রিয়ার নাম লেখো।|মহাকর্ষীয়, তড়িৎচুম্বকীয়, সবল নিউক্লীয় ও দুর্বল নিউক্লীয়। পরিচিত ঘর্ষণ বা সংস্পর্শ বলকে আলাদা পঞ্চম মৌলিক আন্তঃক্রিয়া ধরা হয় না।
মহাকর্ষীয় ও সবল নিউক্লীয় আন্তঃক্রিয়ার পরিসরে মৌলিক পার্থক্য কী?|মহাকর্ষ দীর্ঘ পাল্লার আন্তঃক্রিয়া। সবল নিউক্লীয় বাঁধনের কার্যকর প্রভাব অত্যন্ত স্বল্প, নিউক্লীয় দূরত্বে গুরুত্বপূর্ণ; দুটিকে একই পরিসরের বল বলা যায় না।
একটি বাক্সে অনুভূমিক টান ও ঘর্ষণ সমান হলে কী বলা যায়, কী বলা যায় না?|অনুভূমিক লব্ধ বল ও ত্বরণ শূন্য। কিন্তু বাক্স অবশ্যই স্থির বলা যায় না; আগে চললে সমবেগেও চলতে পারে।
একই ভরবেগ-পরিবর্তনে বলের গড় মান কম হলেই সর্বোচ্চ বল কম—এ দাবি নিশ্চিত কি?|না। গড় মান মোট ঘাত ও সময় নির্ধারণ করে; সময়ের মধ্যে বলের ওঠানামা আলাদা হতে পারে। সর্বোচ্চ মান জানতে বল–সময় তথ্য প্রয়োজন।'''
for line in SHORTS.splitlines():
    q,s=line.split('|');add('SQ',q,s,'concept-short')
assert Counter(q['type'] for q in items)['SQ']==40
for f in ['opposed','momentum-change','average-force','friction','sticking','recoil']:
    for n in range(5):
        q,r,unit,why,p=calc(f,n)
        add('SQ',q.rstrip('।?')+'। সূত্র ও হিসাবের ধাপ দেখাও।',why,'short-'+f,dict(params={k:str(v) for k,v in p.items()},expected=str(r),unit=unit,baseFamily=f))

DEF_F=('নিউটনের দ্বিতীয় সূত্রের ধ্রুব-ভর রূপ লেখো।','একটি জড় কাঠামোয় লব্ধ বল Fনিট = ma।')
DEF_P=('ভরবেগ কী?','ভর ও বেগের গুণফল; p = mv।')
DEF_J=('বলের ঘাত কী?','ধ্রুব বলের ক্ষেত্রে বল ও ক্রিয়াকালের গুণফল; সাধারণভাবে গড় বল × সময়।')
WHY_NET=('একটি বলের বদলে লব্ধ বল নিতে হয় কেন?','বস্তুর ত্বরণ সব বলের ভেক্টর যোগফল দ্বারা নির্ধারিত হয়। প্রতিরোধসহ অন্য বল বাদ দিলে F = ma ভুলভাবে প্রয়োগ হয়।')
WHY_CON=('এই ক্ষেত্রে মোট ভরবেগ সংরক্ষণ কেন ব্যবহার করা যায়?','নির্বাচিত সিস্টেমের ওপর লব্ধ বাহ্যিক ঘাত উপেক্ষণীয় বলা হয়েছে। ভেতরের ক্রিয়া-প্রতিক্রিয়ার ঘাত মোট ভরবেগ বদলায় না।')
WHY_FRICTION=('অভিলম্ব বল এখানে mg কেন?','অন্য উল্লম্ব বল ও উল্লম্ব ত্বরণ নেই। তাই উপরের N ও নিচের mg সমান।')

def cq(f,n,stem,definition,reason,gq,gs,hq,hs,params):
    pairs=[definition,reason,(gq,gs),(hq,hs)]
    parts=[dict(label=l,marks=m,question=q,solution=s) for l,m,(q,s) in zip('কখগঘ',[1,2,3,4],pairs)]
    add('CQ',stem,'সমাধানে একই অক্ষ অনুযায়ী চিহ্ন ও SI একক নাও। লব্ধ বল/বাহ্যিক ঘাতের শর্ত এবং ঘর্ষণের মডেল প্রশ্ন অনুযায়ী প্রযোজ্য; প্রয়োজনমতো ছয় দশমিক পর্যন্ত আসন্ন মান।',f,dict(params={k:str(v) for k,v in params.items()},variant=n+1),parts=parts,difficulty='HARD')

for n in range(5):
    m=3+n;force=12+n*6;t=4+n;a=F(force,m);v=a*t;s=a*t*t/2
    cq('cq-force-accel',n,f'মসৃণ অনুভূমিক পথে স্থির {m} kg ট্রলিতে +{force} N ধ্রুব অনুভূমিক লব্ধ বল {t} s ক্রিয়া করে। উল্লম্ব বলগুলো সাম্যাবস্থায়।',DEF_F,WHY_NET,
       'ট্রলির ত্বরণ ও শেষবেগ নির্ণয় করো।',f'a = {force}/{m} = {fmt(a)} m/s²; v = at = {fmt(v)} m/s।',
       'সরণ নির্ণয় করে বল দ্বিগুণ হলে একই সময়ে কী বদলাত বিচার করো।',f's = ½at² = {fmt(s)} m। ভর ও সময় একই রেখে বল দ্বিগুণে ত্বরণ, শেষবেগ ও সরণ দ্বিগুণ; নতুন সরণ {fmt(2*s)} m।',dict(m=m,force=force,t=t))
    # 2 opposite forces.
    m=4+n;right=30+n*5;left=6+n;t=3+n;net=right-left;a=F(net,m)
    cq('cq-opposed-forces',n,f'{m} kg বাক্সে ডানে {right} N এবং বামে {left} N ধ্রুব বল কাজ করে। অন্য অনুভূমিক বল নেই। বাক্সটি স্থির থেকে শুরু করে {t} s চলে। ডান ধনাত্মক।',DEF_F,WHY_NET,
       'লব্ধ বল ও ত্বরণ নির্ণয় করো।',f'Fনিট = {right}−{left} = {net} N। a = {net}/{m} = {fmt(a)} m/s²।',
       'শেষবেগ নির্ণয় করে শুধু ডানের বল ব্যবহার করলে কত বেশি পাওয়া যেত দেখাও।',f'সঠিক v = at = {fmt(a*t)} m/s। শুধু ডানের বল নিলে vভুল = ({right}/{m})×{t} = {fmt(F(right*t,m))} m/s। বেশি = {fmt(F(left*t,m))} m/s; বামের বল উপেক্ষা করা ভুল।',dict(m=m,right=right,left=left,t=t))
    # 3 forces same direction and balancing.
    m=5+n;F1=10+n*2;F2=15+n*3;net=F1+F2;a=F(net,m)
    cq('cq-same-direction',n,f'{m} kg ব্লকে একই সরলরেখায় ডানদিকে {F1} N ও {F2} N দুটি বল কাজ করে। অন্য অনুভূমিক বল নেই। পরে একটি তৃতীয় বল দিয়ে অনুভূমিক ত্বরণ শূন্য করতে হবে।',DEF_F,
       ('একই বস্তুর সাম্যকারী বল ও তৃতীয় সূত্রের যুগল আলাদা কেন?','সাম্যকারী বলগুলো একই বস্তুর ওপর কাজ করে। ক্রিয়া-প্রতিক্রিয়া যুগল ভিন্ন দুটি বস্তুর ওপর কাজ করে।'),
       'প্রথমে লব্ধ বল ও ত্বরণ নির্ণয় করো।',f'Fনিট = {F1}+{F2} = {net} N ডানে; a = {net}/{m} = {fmt(a)} m/s² ডানে।',
       'তৃতীয় বলের মান ও দিক নির্ণয় করো; সেটি দিলেই বস্তু অবশ্যই স্থির হবে কি?',f'বামে {net} N দিতে হবে; মোট বল 0 N হবে। ত্বরণ শূন্য মানে বেগ অপরিবর্তিত; আগে চললে সমবেগে চলবে, অবশ্যই স্থির হবে না।',dict(m=m,F1=F1,F2=F2))
    # 4 determine mass, compare loading.
    force=20+n*5;a=2+n;m=F(force,a);extra=m
    cq('cq-mass-loading',n,f'এক ট্রলিতে {force} N লব্ধ অনুভূমিক বল দিলে {a} m/s² ত্বরণ হয়। পরে ট্রলির নিজের ভরের সমান অতিরিক্ত মাল যোগ করা হয়; একই লব্ধ বল বজায় থাকে।',DEF_F,
       ('বেশি ভর একই বলের গতিপরিবর্তনকে কমায় কেন?','ভর জড়তার পরিমাপ। a = F/m-এ একই বলের জন্য ভর বাড়লে ত্বরণ কমে।'),
       'প্রথম ট্রলির ভর নির্ণয় করো।',f'm = F/a = {force}/{a} = {fmt(m)} kg।',
       'মাল তোলার পর ত্বরণ নির্ণয় করে তুলনা করো।',f'নতুন ভর = 2m = {fmt(2*m)} kg। aনতুন = {force}/{fmt(2*m)} = {fmt(F(a,2))} m/s², আগের অর্ধেক। একই বল মানে একই ত্বরণ নয়।',dict(force=force,a=a))
    # 5 impulse and force.
    m=2+n;u=3+n;v=10+n*2;t=F(2+n,2);delta=m*(v-u);avg=F(delta)/t
    cq('cq-impulse-change',n,f'{m} kg বস্তুর বেগ একই সরল অক্ষে +{u} m/s থেকে +{v} m/s হয় {fmt(t)} s-এ। এই সময়ে সব বলের লব্ধ ঘাত বিবেচনা করো।',DEF_J,WHY_NET,
       'ভরবেগ-পরিবর্তন ও গড় লব্ধ বল নির্ণয় করো।',f'Δp = {m}({v}−{u}) = {delta} kg·m/s। Fগড় = {delta}/{fmt(t)} = {fmt(avg)} N।',
       'একই ভরবেগ-পরিবর্তন দ্বিগুণ সময়ে ঘটলে গড় বল কত হবে এবং কেন?',f'ঘাত একই {delta} N·s। নতুন সময় {fmt(2*t)} s হলে Fগড় = {delta}/{fmt(2*t)} = {fmt(avg/2)} N। সময় দ্বিগুণ বলে গড় বল অর্ধেক; সর্বোচ্চ বলও ঠিক অর্ধেক এমন নিশ্চয়তা নেই।',dict(m=m,u=u,v=v,t=t))
    # 6 stopping over distance.
    m=5+n;u=12+n*2;distance=18+n*6;b=F(u*u,2*distance);force=m*b
    cq('cq-stop-distance',n,f'{m} kg ট্রলি {u} m/s আদিদ্রুতি নিয়ে সোজা পথে {distance} m গিয়ে থামে। ধ্রুব লব্ধ বাধাদানকারী বল থামা পর্যন্ত ক্রিয়া করে; অন্য পর্ব নেই।',DEF_F,
       ('বাধাদানকারী বলের দিক কী হবে?','এখানে বেগের বিপরীতে লব্ধ বল থাকায় দ্রুতি কমে। আদিবেগকে ধনাত্মক ধরলে ত্বরণ ঋণাত্মক।'),
       'মন্দন ও বাধাদানকারী বলের মান নির্ণয় করো।',f'b = u²/(2s) = {u}²/(2×{distance}) = {fmt(b)} m/s²। F = mb = {fmt(force)} N।',
       'একই মন্দনে আদিদ্রুতি দ্বিগুণ হলে থামার পথ ও সময় তুলনা করো।',f'নতুন পথ = 4×{distance} = {4*distance} m। প্রথম সময় u/b = {fmt(F(u)/b)} s; নতুন সময় = {fmt(F(2*u)/b)} s, দ্বিগুণ। দূরত্ব চারগুণ হওয়ার কারণ s ∝ u²।',dict(m=m,u=u,distance=distance))
    # 7 soft vs hard stopping.
    m=F(2+n,10);u=15+n*5;short=F(1,100);long=F(5,100);J=m*u
    cq('cq-impact-time',n,f'{fmt(m)} kg বল অনুভূমিকভাবে {u} m/s বেগে এসে থামে। শক্ত বাধায় সময় {fmt(short)} s, নরম বাধায় {fmt(long)} s। উভয় ক্ষেত্রে ফিরে আসে না; অন্য অনুভূমিক ঘাত উপেক্ষণীয়।',DEF_J,
       ('নরম বাধায় কম আঘাতের ব্যাখ্যায় কোন সময়টি গুরুত্বপূর্ণ?','বল থামতে যত সময় নেয় সেটি। একই ভরবেগ-পরিবর্তন বেশি সময়ে হলে গড় বাধাদানকারী বল কমে।'),
       'দুই ক্ষেত্রে ঘাতের মান ও গড় বলের মান নির্ণয় করো।',f'উভয় ঘাতের মান = mu = {fmt(J)} N·s। শক্তে F = {fmt(J/short)} N; নরমে F = {fmt(J/long)} N।',
       'বলগুলোর অনুপাত বের করে একই ঘাত মানেই একই বল নয় কেন বোঝাও।',f'Fশক্ত/Fনরম = {fmt(long/short)}। ঘাত একই {fmt(J)} N·s, কিন্তু সময় {fmt(long/short)} গুণ হলে গড় বল তত গুণ কমে। গড় বল দিয়ে পুরো বল–সময় প্রোফাইল নির্ধারিত হয় না।',dict(m=m,u=u,short=short,long=long))
    # 8 rebound signs.
    m=F(1+n,10);u=10+n*2;back=6+n;t=F(2+n,100);J=-m*(back+u)
    cq('cq-rebound',n,f'{fmt(m)} kg বল ডানদিকে +{u} m/s বেগে দেয়ালে লেগে বামদিকে {back} m/s বেগে ফিরে আসে। সংস্পর্শকাল {fmt(t)} s; অন্য অনুভূমিক ঘাত নেই। ডান ধনাত্মক।',DEF_P,
       ('ফিরে আসার বেগে ঋণাত্মক চিহ্ন কেন দিতে হয়?','অক্ষের ধনাত্মক দিক ডান; ফেরার দিক বাম। তাই শেষবেগ −v, শুধু দ্রুতির মান বিয়োগ করলে দিকের তথ্য হারায়।'),
       'বলের ঘাত ও গড় বল নির্ণয় করো।',f'Δp = m(v−u) = {fmt(m)}(−{back}−{u}) = {fmt(J)} N·s। Fগড় = Δp/Δt = {fmt(J/t)} N; দুটিই বামে।',
       'একই আদিবেগ থেকে শুধু থামলে ঘাতের মান কত হতো? ফিরে আসার সঙ্গে তুলনা করো।',f'শুধু থামলে |J| = mu = {fmt(m*u)} N·s। ফিরে আসলে |J| = {fmt(-J)} N·s; অতিরিক্ত = m×{back} = {fmt(m*back)} N·s। দিক উল্টাতে বেশি ভরবেগ-পরিবর্তন দরকার।',dict(m=m,u=u,back=back,t=t))
    # 9 moving and stationary stick.
    m1=2+n;m2=3+n;u=10+n*2;V=F(m1*u,m1+m2)
    cq('cq-stick-stationary',n,f'মসৃণ অনুভূমিক পথে {m1} kg গাড়ি ডানে {u} m/s বেগে এসে স্থির {m2} kg গাড়িতে লেগে যায়। সংঘর্ষকালে বাহ্যিক অনুভূমিক ঘাত শূন্য।',DEF_P,WHY_CON,
       'যৌথ বেগ নির্ণয় করো।',f'{m1}×{u} = ({m1}+{m2})V, তাই V = {fmt(V)} m/s ডানে।',
       'দুই গাড়ির পৃথক ভরবেগ-পরিবর্তন নির্ণয় করে তাদের যোগ পরীক্ষা করো।',f'প্রথমের Δp₁ = {m1}({fmt(V)}−{u}) ≈ {fmt(m1*(V-u))} kg·m/s। দ্বিতীয়ের Δp₂ = {m2}×V ≈ {fmt(m2*V)} kg·m/s। ঠিক মানে যোগ 0; অভ্যন্তরীণ ঘাত সমান বিপরীত।',dict(m1=m1,m2=m2,u=u))
    # 10 head-on sticking unequal masses.
    m1=3+n;m2=2+n;u=8+n;back=3+n;V=F(m1*u-m2*back,m1+m2)
    cq('cq-headon-stick',n,f'ডান ধনাত্মক অক্ষে {m1} kg গাড়ির বেগ +{u} m/s, {m2} kg গাড়ির বেগ −{back} m/s। তারা মুখোমুখি ধাক্কা খেয়ে লেগে যায়। বাহ্যিক অনুভূমিক ঘাত শূন্য।',DEF_P,WHY_CON,
       'সংঘর্ষের পর যৌথ বেগ ও দিক নির্ণয় করো।',f'আগের মোট p = {m1}×{u}−{m2}×{back} = {m1*u-m2*back} kg·m/s। V = p/({m1}+{m2}) = {fmt(V)} m/s, ডানে।',
       'দ্বিতীয় গাড়ির ভরবেগ-পরিবর্তন বের করে বেগের চিহ্ন বাদ দিলে কী ভুল হতো ব্যাখ্যা করো।',f'Δp₂ = {m2}[V−(−{back})] ≈ {fmt(m2*(V+back))} kg·m/s। চিহ্ন ছাড়া মোট আদিভরবেগ {m1*u+m2*back} লেখা হতো, যা ভুল; বিপরীত দিকের ভরবেগ বিয়োগ করতে হয়।',dict(m1=m1,m2=m2,u=u,back=back))
    # 11 recoil.
    bullet=F(n+1,100);speed=120+n*30;gun=3+n;recoil=-bullet*speed/gun
    cq('cq-gun-recoil',n,f'স্থির বন্দুক থেকে {fmt(bullet)} kg গুলি ডানে {speed} m/s ভূমি-সাপেক্ষ বেগে বেরোয়। বের হওয়ার পর বন্দুকের ভর {gun} kg। বাহ্যিক অনুভূমিক ঘাত শূন্য; ডান ধনাত্মক।',DEF_P,WHY_CON,
       'বন্দুকের পশ্চাদ্বেগ নির্ণয় করো।',f'0 = mv+MV; V = −({fmt(bullet)}×{speed})/{gun} = {fmt(recoil)} m/s।',
       'একই গুলি ও ভূমি-সাপেক্ষ গুলিবেগ রেখে বন্দুকের ভর দ্বিগুণ হলে কী বদলাবে?',f'নতুন V = {fmt(recoil/2)} m/s, পশ্চাদ্বেগের মান অর্ধেক। গুলির p = {fmt(bullet*speed)} kg·m/s অপরিবর্তিত; বেশি বন্দুকভর সমান বিপরীত ভরবেগ কম বেগে পায়।',dict(bullet=bullet,speed=speed,gun=gun))
    # 12 two pieces explosion.
    m1=2+n;m2=5+n;v1=10+n*2;v2=-F(m1*v1,m2)
    cq('cq-explosion',n,f'মসৃণ অনুভূমিক তলে স্থির একটি সিস্টেম অন্তর্গত প্রক্রিয়ায় {m1} kg ও {m2} kg দুই টুকরায় আলাদা হয়। প্রথমটি ডানে {v1} m/s চলে। বাহ্যিক অনুভূমিক ঘাত নেই।',DEF_P,WHY_CON,
       'দ্বিতীয় টুকরার বেগ ও দিক নির্ণয় করো।',f'0 = {m1}×{v1}+{m2}v₂; v₂ = {fmt(v2)} m/s, বামে।',
       'দুটি টুকরার ভরবেগ তুলনা করে মোট ভরবেগ শূন্য মানে স্থির কি না বিচার করো।',f'p₁ = {m1*v1} kg·m/s, p₂ = {fmt(m2*v2)} kg·m/s; যোগ 0। পৃথক বেগ {v1} ও {fmt(v2)} m/s অশূন্য; মোট ভরবেগ শূন্য মানে প্রতিটি বস্তু স্থির নয়।',dict(m1=m1,m2=m2,v1=v1))
    # 13 same direction coupling.
    m1=4+n;m2=6+n;u=9+n;v=3+n;V=F(m1*u+m2*v,m1+m2)
    cq('cq-coupling-moving',n,f'একই দিকে চলা {m1} kg গাড়ির বেগ {u} m/s ও সামনে থাকা {m2} kg গাড়ির বেগ {v} m/s। পেছনেরটি ধরে লেগে যায়। বাহ্যিক অনুভূমিক ঘাত শূন্য।',DEF_P,WHY_CON,
       'যৌথ বেগ নির্ণয় করো।',f'V = ({m1}×{u}+{m2}×{v})/({m1}+{m2}) = {fmt(V)} m/s, আগের দিকেই।',
       'যৌথ বেগ দুই আদিবেগের মাঝখানে কেন? পৃথক ভরবেগ বদল দিয়ে ব্যাখ্যা করো।',f'Δp₁ ≈ {fmt(m1*(V-u))} kg·m/s; Δp₂ ≈ {fmt(m2*(V-v))} kg·m/s; যোগ 0। দ্রুতটি ভরবেগ হারায়, ধীরটি পায়। ভর-ওজনযুক্ত গড় V = {fmt(V)} m/s, যা {v} ও {u}-এর মধ্যে।',dict(m1=m1,m2=m2,u=u,v=v))
    # 14 kinetic friction net.
    m=4+n;mu=F(2+n,10);g=10;pull=30+n*10;fr=mu*m*g;a=F(pull-fr,m)
    cq('cq-friction-net',n,f'{m} kg ব্লক সমতল মেঝেতে ডানে পিছলাচ্ছে। ডানে অনুভূমিক টান {pull} N, μₖ = {fmt(mu)}, g = 10 m/s²। অন্য উল্লম্ব বল বা ত্বরণ নেই। f = μₖN মডেল নাও।',DEF_F,WHY_FRICTION,
       'ঘর্ষণ ও অনুভূমিক ত্বরণ নির্ণয় করো।',f'N = mg = {m*g} N। f = μₖN = {fmt(fr)} N বামে। a = ({pull}−{fmt(fr)})/{m} = {fmt(a)} m/s² ডানে।',
       'সমবেগে পিছলানো বজায় রাখতে টান কত হওয়া দরকার? বর্তমান টানের সঙ্গে তুলনা করো।',f'সমবেগে লব্ধ বল 0, তাই টান = f = {fmt(fr)} N। বর্তমান টান এর চেয়ে {fmt(pull-fr)} N বেশি বলে ত্বরণ আছে; সমবেগের জন্য বলগুলো সাম্য করতে হবে।',dict(m=m,mu=mu,g=g,pull=pull))
    # 15 infer coefficient from uniform motion.
    m=5+n;g=10;pull=10+n*4;mu=F(pull,m*g);extra=6+n
    cq('cq-friction-uniform',n,f'{m} kg বাক্স সমতল মেঝেতে {pull} N অনুভূমিক টানে সমবেগে পিছলায়। g = 10 m/s²; অন্য উল্লম্ব বল বা ত্বরণ নেই। f = μₖN মডেলে সহগ অপরিবর্তিত। পরে টান আরও {extra} N বাড়ে।',DEF_F,WHY_FRICTION,
       'গতিঘর্ষণ সহগ নির্ণয় করো।',f'সমবেগে f = {pull} N। N = {m*g} N; μₖ = {pull}/{m*g} = {fmt(mu)}।',
       'টান বাড়ানোর পর ত্বরণ নির্ণয় করে সমবেগের শর্তের পার্থক্য বোঝাও।',f'নতুন টান = {pull+extra} N; একই f = {pull} N। লব্ধ = {extra} N, a = {extra}/{m} = {fmt(F(extra,m))} m/s²। প্রথমে সাম্য ছিল; টান বাড়ালে তা আর থাকে না।',dict(m=m,g=g,pull=pull,extra=extra))
    # 16 static below limit.
    m=5+n;g=10;mu=F(4,10);limit=mu*m*g;pull=limit-F(5);above=limit+F(5)
    cq('cq-static-limit',n,f'সমতল মেঝেতে স্থির {m} kg ব্লকের μₛ = 0.4, g = 10 m/s²। প্রথমে অনুভূমিক টান {fmt(pull)} N, পরে {fmt(above)} N করা হয়। অন্য উল্লম্ব বল/ত্বরণ নেই; fₛ,max = μₛN।',('সর্বোচ্চ স্থিতি ঘর্ষণ কী?','আপেক্ষিক পিছলানো শুরুর ঠিক আগে স্থিতি ঘর্ষণের সর্বোচ্চ মান।'),WHY_FRICTION,
       'প্রথম অবস্থায় প্রকৃত স্থিতি ঘর্ষণ ও সর্বোচ্চ সীমা নির্ণয় করো।',f'fₛ,max = 0.4×{m}×10 = {fmt(limit)} N। প্রথম টান সীমার নিচে, তাই প্রকৃত fₛ = {fmt(pull)} N বিপরীতে; সবসময় সর্বোচ্চ মান নয়।',
       'পরের টানে স্থির থাকা সম্ভব কি? চলা শুরুর পর ত্বরণ কেন শুধু এই উপাত্তে নির্ণয় করা যায় না?',f'{fmt(above)} N > {fmt(limit)} N, তাই পিছলানো শুরু হবে। কিন্তু μₖ বা গতিঘর্ষণের মান নেই; μₛ দিয়ে চলমান অবস্থার ঘর্ষণ নিশ্চিত নয়। তাই চলা শুরুর পর নির্দিষ্ট ত্বরণ দাবি করা যাবে না।',dict(m=m,g=g,mu=mu,pull=pull,above=above))
    # 17 compare two kinetic surfaces.
    m=6+n;g=10;mu1=F(1,10);mu2=F(3,10);fr1=mu1*m*g;fr2=mu2*m*g
    cq('cq-friction-surfaces',n,f'একই {m} kg ব্লক দুটি সমতল মেঝেতে আলাদাভাবে সমবেগে পিছলানো হয়। প্রথমে μₖ = 0.1, দ্বিতীয়তে 0.3; g = 10 m/s²। কেবল অনুভূমিক টান; অন্য উল্লম্ব বল/ত্বরণ নেই। f = μₖN।',DEF_F,WHY_FRICTION,
       'দুটি পৃষ্ঠে প্রয়োজনীয় টানের মান নির্ণয় করো।',f'সমবেগে টান ঘর্ষণের সমান। প্রথমে {fmt(fr1)} N, দ্বিতীয়তে {fmt(fr2)} N।',
       'দ্বিতীয়টির জন্য প্রয়োজনীয় টান প্রথম পৃষ্ঠে দিলে ত্বরণ কত হবে? তুলনা করো।',f'প্রথম পৃষ্ঠে লব্ধ = {fmt(fr2-fr1)} N। a = ({fmt(fr2)}−{fmt(fr1)})/{m} = {fmt((fr2-fr1)/m)} m/s²। টান সমান হলেও পৃষ্ঠের সহগ আলাদা হলে ত্বরণ বদলায়।',dict(m=m,g=g,mu1=mu1,mu2=mu2))
    # 18 friction-only braking.
    m=5+n;g=10;mu=F(2+n,10);u=12+n*3;b=mu*g;T=F(u)/b;S=F(u*u)/(2*b)
    cq('cq-friction-braking',n,f'{m} kg ব্লক সমতল মেঝেতে {u} m/s বেগে পিছলাচ্ছে। অনুভূমিকভাবে শুধু গতিঘর্ষণ কাজ করে; μₖ = {fmt(mu)}, g = 10 m/s²। অন্য উল্লম্ব বল/ত্বরণ নেই। f = μₖN মডেল থামা পর্যন্ত নাও।',DEF_F,WHY_FRICTION,
       'মন্দন ও থামার সময় নির্ণয় করো।',f'f = μₖmg; b = f/m = μₖg = {fmt(b)} m/s²। t = u/b = {fmt(T)} s।',
       'থামার দূরত্ব এবং একই μₖ-তে ভর দ্বিগুণ হলে কী হবে বিচার করো।',f's = u²/(2b) = {fmt(S)} m। একই μₖ, g ও u-তে b = μₖg ভর-নিরপেক্ষ; ভর দ্বিগুণে ঘর্ষণ দ্বিগুণ হলেও ত্বরণ ও থামার দূরত্ব অপরিবর্তিত। এটি প্রদত্ত সরল মডেলের ফল।',dict(m=m,g=g,mu=mu,u=u))
    # 19 two blocks contact.
    m1=2+n;m2=3+n;push=20+n*10;a=F(push,m1+m2);contact=m2*a
    cq('cq-blocks-contact',n,f'মসৃণ অনুভূমিক তলে পরস্পর সংলগ্ন {m1} kg ও {m2} kg ব্লক আছে। প্রথমটির ওপর ডানে {push} N বল দিয়ে দ্বিতীয়টিকে ঠেলা হয়। দুইটি একসঙ্গে একই ত্বরণে চলে; অন্য অনুভূমিক বাহ্যিক বল নেই।',DEF_F,
       ('দুই ব্লককে এক সিস্টেম ধরলে সংস্পর্শ বল কেন যোগ করতে হয় না?','পরস্পরের সংস্পর্শ বলগুলো সিস্টেমের অভ্যন্তরীণ সমান বিপরীত বল। মোট বাহ্যিক লব্ধ বলে সেগুলো বাতিল হয়।'),
       'দুই ব্লকের সাধারণ ত্বরণ নির্ণয় করো।',f'a = {push}/({m1}+{m2}) = {fmt(a)} m/s²।',
       'দ্বিতীয় ব্লকের ওপর প্রথমটির সংস্পর্শ বল এবং প্রথমটির লব্ধ বল বের করো।',f'দ্বিতীয়টির একমাত্র অনুভূমিক বল C = m₂a = {fmt(contact)} N ডানে। প্রথমটিতে প্রতিক্রিয়া বামে; লব্ধ = {push}−C = {fmt(m1*a)} N = m₁a। ক্রিয়া-প্রতিক্রিয়া ভিন্ন ব্লকে কাজ করে।',dict(m1=m1,m2=m2,push=push))
    # 20 two connected carts, external pull on first.
    m1=3+n;m2=5+n;pull=24+n*8;a=F(pull,m1+m2);tension=m2*a
    cq('cq-carts-tension',n,f'মসৃণ অনুভূমিক পথে হালকা অপ্রসারণশীল সুতোয় যুক্ত {m1} kg ও {m2} kg গাড়ি। প্রথম গাড়িকে ডানে {pull} N বাহ্যিক বল টানে; দ্বিতীয়টি পেছনে। সুতো টানটান, ভর উপেক্ষণীয়; অন্য অনুভূমিক বল নেই।',DEF_F,
       ('দুই গাড়ির ত্বরণ এক কেন?','সুতো অপ্রসারণশীল ও টানটান; তাদের বিচ্ছেদ স্থির থাকে। একই সরলদিকে উভয়ের বেগ-পরিবর্তনের হার সমান।'),
       'সাধারণ ত্বরণ নির্ণয় করো।',f'a = {pull}/({m1}+{m2}) = {fmt(a)} m/s²।',
       'সুতোর টান ও প্রথম গাড়ির লব্ধ বল নির্ণয় করে বাহ্যিক বলকে টান বলা যাবে কি বিচার করো।',f'T = m₂a = {fmt(tension)} N। প্রথম গাড়ির লব্ধ = {pull}−T = {fmt(m1*a)} N। বাহ্যিক টান {pull} N, সুতোর টান {fmt(tension)} N; প্রথম গাড়িকেও ত্বরিত করতে হয় বলে দুটি সমান নয়।',dict(m1=m1,m2=m2,pull=pull))
    # 21 vertical support/elevator.
    m=40+n*5;g=10;a=1+n;N=m*(g+a)
    cq('cq-vertical-support',n,f'{m} kg ব্যক্তি একটি লিফটের মেঝেতে দাঁড়িয়ে আছেন। লিফট ওপরে {a} m/s² ত্বরণে চলছে। g = 10 m/s²; ব্যক্তির ওপর শুধু ওজন ও মেঝের অভিলম্ব বল কাজ করে।',('ওজন কী?','বস্তুর ওপর মহাকর্ষীয় বল; W = mg।'),
       ('অভিলম্ব বল সবসময় ওজনের সমান নয় কেন?','উল্লম্ব ত্বরণে N−mg = ma। তাই ত্বরণ শূন্য না হলে সাধারণত N ও mg সমান হয় না।'),
       'ব্যক্তির ওপর অভিলম্ব বল নির্ণয় করো।',f'ওপরে ধনাত্মক; N−mg = ma। N = {m}(10+{a}) = {N} N।',
       'লিফট একই বেগে ওপরে চললে অভিলম্ব বল কত হতো? দুই অবস্থায় ভর ও প্রকৃত ওজন বদলায় কি?',f'সমবেগে a = 0, তাই N = mg = {m*g} N। প্রথম ক্ষেত্রে N বেশি {m*a} N। ভর {m} kg ও প্রকৃত ওজন {m*g} N একই থাকে; অভিলম্ব বল বা আপাত ওজন বদলায়।',dict(m=m,g=g,a=a))
    # 22 identical impulses, different masses.
    m1=2+n;m2=2*m1;force=12+n*4;t=3+n;J=force*t;v1=F(J,m1);v2=F(J,m2)
    cq('cq-equal-force-masses',n,f'আলাদা দুটি স্থির গাড়ির ভর {m1} kg ও {m2} kg। প্রত্যেকের ওপর একই দিকে {force} N ধ্রুব লব্ধ বল সমান {t} s ক্রিয়া করে।',DEF_J,
       ('একই বল একই সময়ে প্রয়োগে কী সমান হয়?','লব্ধ ঘাত FΔt সমান, তাই ভরবেগ-পরিবর্তনও সমান। ভর ভিন্ন হলে বেগ-পরিবর্তন সমান হওয়া জরুরি নয়।'),
       'দুই গাড়ির শেষবেগ নির্ণয় করো।',f'J = {force}×{t} = {J} N·s। v₁ = J/m₁ = {fmt(v1)} m/s; v₂ = J/m₂ = {fmt(v2)} m/s।',
       'দুইটির শেষ ভরবেগ ও বেগের অনুপাত তুলনা করো।',f'p₁ = p₂ = {J} kg·m/s। কিন্তু v₁/v₂ = {fmt(v1/v2)}। দ্বিতীয় ভর দ্বিগুণ হওয়ায় একই ভরবেগ পেতে বেগ অর্ধেক; ভরবেগ সমান মানেই বেগ সমান নয়।',dict(m1=m1,m2=m2,force=force,t=t))
    # 23 time-dependent force data, piecewise constants.
    m=3+n;F1=10+n*2;t1=2+n;F2=4+n;t2=3+n;J=F1*t1-F2*t2;v=F(J,m)
    cq('cq-piecewise-force',n,f'স্থির {m} kg বস্তুতে প্রথম {t1} s লব্ধ বল +{F1} N, পরের {t2} s লব্ধ বল −{F2} N। প্রতিটি পর্বে বল ধ্রুব; ডান ধনাত্মক। অন্য বল ইতিমধ্যে লব্ধ মানে অন্তর্ভুক্ত।',DEF_J,
       ('বল–সময় লেখচিত্রে অক্ষের নিচের ক্ষেত্রফল কী বোঝায়?','ঋণাত্মক দিকে বলের ঘাত বোঝায়। মোট দিকযুক্ত ঘাতে এই ক্ষেত্রফল বিয়োগ করতে হয়।'),
       'মোট ঘাত ও শেষবেগ নির্ণয় করো।',f'J = {F1}×{t1}−{F2}×{t2} = {J} N·s। v = J/m = {fmt(v)} m/s, ডানে।',
       'পুরো সময়ে গড় লব্ধ বল নির্ণয় করে মানের যোগফল দিয়ে হিসাবের ভুল বোঝাও।',f'Fগড় = {J}/({t1}+{t2}) = {fmt(F(J,t1+t2))} N। ঋণাত্মক অংশকে ধনাত্মক যোগ করলে ঘাত {F1*t1+F2*t2} N·s হয়, যা ভুল। বলের দিক বদলালে বীজগাণিতিক ক্ষেত্রফল নিতে হয়।',dict(m=m,F1=F1,t1=t1,F2=F2,t2=t2))
    # 24 external impulse breaks isolated conservation.
    m1=2+n;m2=3+n;u=8+n;force=5+n;dt=F(2,10);J=force*dt;V=F(m1*u+J,m1+m2);V0=F(m1*u,m1+m2)
    cq('cq-external-impulse',n,f'{m1} kg গাড়ি ডানে {u} m/s বেগে স্থির {m2} kg গাড়িতে লেগে যায়। সংঘর্ষের {fmt(dt)} s-এ দুই গাড়ির সিস্টেমের ওপর ডানে {force} N গড় লব্ধ বাহ্যিক বলও থাকে। ডান ধনাত্মক।',DEF_J,
       ('এখানে আগের মোট ভরবেগ সরাসরি পরের সমান করা যাবে না কেন?','বাহ্যিক ঘাত অশূন্য। সঠিক সম্পর্ক pপর = pআগে + Jবাহ্যিক; অভ্যন্তরীণ বলের বাতিল হওয়া বাহ্যিক ঘাত বাদ দেয় না।'),
       'বাহ্যিক ঘাত ও যৌথ বেগ নির্ণয় করো।',f'Jবাহ্যিক = {force}×{fmt(dt)} = {fmt(J)} N·s। V = ({m1}×{u}+{fmt(J)})/({m1}+{m2}) = {fmt(V)} m/s।',
       'বাহ্যিক বল উপেক্ষা করলে বেগের কত ভুল হতো? পার্থক্যের কারণ লেখো।',f'উপেক্ষায় V₀ = {fmt(V0)} m/s। সঠিক V−V₀ = Jবাহ্যিক/(m₁+m₂) = {fmt(V-V0)} m/s। বাহ্যিক ঘাত মোট ভরবেগ বাড়িয়েছে; সংরক্ষণ সূত্রের শর্ত বাদ দেওয়া যাবে না।',dict(m1=m1,m2=m2,u=u,force=force,dt=dt))

assert Counter(q['type'] for q in items)=={'MCQ':200,'CQ':120,'SQ':70}
assert len(set(q['text'] for q in items))==390

def enc(x):return json.dumps(x,ensure_ascii=False,indent=2)+'\n'
def artifact(p,s):
    if '--check' in sys.argv:assert p.exists() and p.read_text()==s,f'Stale: {p}'
    else:p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)

slices={'mcq':[q for q in items if q['type']=='MCQ'],'cq':[q for q in items if q['type']=='CQ'],'sq':[q for q in items if q['type']=='SQ']}
for name,rows in slices.items():
    b=dict(category='Class 9',subject='পদার্থবিজ্ঞান',topic=TOPIC,book='নিজস্ব অনুশীলনী; উৎস পৃষ্ঠা/বোর্ড আরোপ নয়',edition='নবম–দশম বল অনুশীলনী খসড়া v1; শিক্ষক যাচাই বাকি',sourceUrl='https://github.com/saifulsirictdev/Proshnobook_com',lang='Bangla',items=rows)
    s=enc(b);assert len(rows)<=200 and len(s.encode())<750000;artifact(OUT/f'{name}.json',s)
