blocks=[]
for kind,title in [('MCQ','বহুনির্বাচনি'),('CQ','সৃজনশীল'),('SQ','সংক্ষিপ্ত')]:
    blocks.append(f'<h2>{title}</h2>')
    for i,q in enumerate([x for x in items if x['type']==kind],1):
        b=f'<h3>{i}. {html.escape(q["text"])}</h3>'
        if kind=='MCQ':
            b+='<div class="options">'+''.join(f'<p>{k}. {html.escape(v)}</p>' for k,v in q['options'].items())+'</div>'
            b+=f'<p class="answer">উত্তর: {q["correct"]} — {html.escape(q["explanation"])}</p>'
        elif kind=='CQ':b+=''.join(f'<p><b>{p["label"]}) ({p["marks"]}) {html.escape(p["question"])}</b></p><p class="answer">{html.escape(p["solution"])}</p>' for p in q['parts'])
        else:b+=f'<p class="answer">{html.escape(q["explanation"])}</p>'
        blocks.append('<article>'+b+'</article>')
artifact(DOC/'chapter-3-review.html','''<!doctype html><html lang="bn"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SSC পদার্থবিজ্ঞান — অধ্যায় ৩ বল খসড়া</title><style>body{max-width:950px;margin:32px auto;padding:0 20px;font:18px/1.8 system-ui,sans-serif;color:#17263d}h1,h2{color:#175950}h2{border-bottom:2px solid;padding-top:24px}article{border-bottom:1px solid #cdd6d9;padding:14px 0;break-inside:avoid}h3{font-size:1.05em}.answer{background:#eff6f4;padding:10px 16px}.options{display:grid;grid-template-columns:1fr 1fr}.notice{background:#fff4d6;padding:20px}@media print{body{margin:0;font-size:11pt}h2{break-before:page}}</style><h1>পদার্থবিজ্ঞান — তৃতীয় অধ্যায়: বল</h1><div class="notice"><b>পর্যালোচনাধীন নিজস্ব খসড়া — প্রকাশিত নয়</b><p>২০০ MCQ + ১২০ CQ + ৭০ সংক্ষিপ্ত। একই পরিবারের সংখ্যাভিত্তিক ভ্যারিয়েন্ট আছে; ৩৯০টি স্বাধীন ধারণা নয়। মূল বইয়ের পূর্ণ পাঠ/পৃষ্ঠা, প্রয়োগগুলোর পাঠ্যসীমা ও স্বাধীন শিক্ষক যাচাই বাকি। বোর্ডের হুবহু প্রশ্ন নয়। বলের দিক ও গ্রাফের তথ্য কথায় দেওয়া; সরাসরি বলচিত্র পড়া/আঁকার বিকল্প নয়।</p><p>আগের ছবির কাঠামো: ২৫ MCQ সব উত্তর (২৫), ৭ CQ থেকে ৪টি (৪০), ৭ সংক্ষিপ্ত থেকে ৫টি (১০)। তত্ত্বীয় ৭৫, ব্যবহারিক ২৫; সময় ৩ ঘণ্টা। নির্দিষ্ট সরকারি সাল যাচাই করা হয়নি। এই ভান্ডার পূর্ণ সিলেবাসের মডেল নয়।</p></div>'''+''.join(blocks)+'</html>\n')
